    assert grid.ndim == 4, "The ndim of grid must be 4"
    assert grid.shape[-1] == 2, "The last dimension of grid must be 2"

    N, C, IH, IW = input.shape
    _, OH, OW, _ = grid.shape

    # The kernel computes flat offsets assuming contiguous layouts.
    input = input.contiguous()
    grid = grid.contiguous()

    # allocate output
    output = torch.empty((N, C, OH, OW), device=input.device, dtype=input.dtype)
    total_threads = OH * OW
    if output.numel() == 0:
        return output
    grid_lambda = lambda META: (
        triton.cdiv(total_threads, META["BLOCK_SIZE"]),
        N * C,
    )

